// Confere cada ocorrência e registra a reclamação no canal oficial.
// MVP: o registro é SIMULADO (gera um protocolo SIM-...). Para o canal real, troque este nó por
// um "Send Email" para a ouvidoria ou um HTTP Request para o formulário da SPTrans.
const saida = [];
for (const item of $input.all()) {
  const oc = item.json;
  const ev = oc.evidencias || {};
  const passagem = ev.passagem || {};
  const aviso = ev.aviso || {};
  const temLinha = Boolean(oc.linha);
  // evidência: a câmera leu o letreiro com confiança, ou o motorista confirmou o aviso no bipper
  const temEvidencia = (passagem.camera_ok === true && (passagem.confianca || 0) >= 0.6) || Boolean(aviso.ciente_em);
  if (!oc.consentimento || !temLinha) {
    saida.push({ json: { id: oc.id, status: 'inconclusiva', protocolo: null,
      mensagem: 'sem consentimento ou sem linha identificada' } });
    continue;
  }
  if (!temEvidencia) {
    saida.push({ json: { id: oc.id, status: 'inconclusiva', protocolo: null,
      mensagem: 'evidências fracas (sem leitura da câmera nem ciente do motorista)' } });
    continue;
  }
  const protocolo = 'SIM-' + Math.random().toString(36).slice(2, 10).toUpperCase();
  const texto = `Ônibus da linha ${oc.linha}${oc.prefixo ? ' (prefixo ' + oc.prefixo + ')' : ''} ` +
    `não parou para passageiro com deficiência visual no ponto ${(ev.parada && ev.parada.nome) || oc.parada_id} em ${passagem.em || oc.criado_em}. ` +
    `Registro automático do Sonar.`;
  saida.push({ json: { id: oc.id, status: 'enviada', protocolo, mensagem: texto } });
}
return saida;

const itens = $input.all().map(i => i.json);
const enviadas = itens.filter(i => i.status === 'enviada').length;
return [{ json: { processadas: itens.length, enviadas, inconclusivas: itens.length - enviadas,
  em: new Date().toISOString() } }];
